#!/bin/sh
# mkkreg.sh -- kbootset/kreg.c from abi/registry/majors: the major registry
# kbootset's gate 3 checks a module's majors= against (C3-5 section 2), the
# same table the module core is built with (core tools/mkreg).
#
# usage: sh tools/mkkreg.sh > kbootset/kreg.c
# make test checks that the tracked kreg.c is what this writes.
#
# Copyright (c) 2026 Jussi Alanärä.  MIT licence, see LICENSE.
set -e
R=$(cd "$(dirname "$0")/.." && pwd)
cat <<'HEAD'
/*
 * kreg.c -- generated by tools/mkkreg.sh from abi/registry/majors: the
 * majors each module owns (docs/spec/20-module-format-and-abi.md section 6).
 * Do not edit; edit the registry and run the tool.
 *
 * Copyright (c) 2026 Jussi Alanärä.  MIT licence, see LICENSE.
 */
#include <string.h>
#include "kmod.h"

static const struct { int type, n; const char *name; } reg[] = {
HEAD
sed 's/#.*//' "$R/abi/registry/majors" | awk 'NF == 3 { printf "\t{ '\''%s'\'', %d, \"%s\" },\n", $1, $2, $3 }'
cat <<'TAIL'
	{ 0, 0, 0 }
};

const char *
km_owner(int type, int n)
{
	int i;

	for (i = 0; reg[i].type; i++)
		if (reg[i].type == type && reg[i].n == n)
			return reg[i].name;
	return 0;
}

const char *
km_entry(int i, int *type, int *n)
{
	int j;

	for (j = 0; j < i && reg[j].type; j++)
		;
	if (i < 0 || !reg[j].type)
		return 0;
	*type = reg[j].type;
	*n = reg[j].n;
	return reg[j].name;
}
TAIL
